def transform(grid):
    h, w = len(grid), len(grid[0])

    sep_rows = [r for r in range(h) if grid[r][0] != 0 and all(v == grid[r][0] for v in grid[r])]
    sep_cols = [c for c in range(w) if grid[0][c] != 0 and all(grid[r][c] == grid[0][c] for r in range(h))]
    sep_color = grid[sep_rows[0]][0] if sep_rows else (grid[0][sep_cols[0]] if sep_cols else -1)

    def bands(length, separators):
        result = []
        start = 0
        for i in separators:
            if start < i:
                result.append((start, i))
            start = i + 1
        if start < length:
            result.append((start, length))
        return result

    rb = bands(h, sep_rows)
    cb = bands(w, sep_cols)
    out = [row[:] for row in grid]
    colors = {v for row in grid for v in row if v not in (0, sep_color)}

    for color in colors:
        panels = []
        for r0, r1 in rb:
            row_panels = []
            for c0, c1 in cb:
                row_panels.append({
                    (r - r0, c - c0)
                    for r in range(r0, r1)
                    for c in range(c0, c1)
                    if grid[r][c] == color
                })
            panels.append(row_panels)

        for i in range(len(rb) - 1):
            for j in range(len(cb) - 1):
                heights = (rb[i][1] - rb[i][0], rb[i + 1][1] - rb[i + 1][0])
                widths = (cb[j][1] - cb[j][0], cb[j + 1][1] - cb[j + 1][0])
                if heights[0] != heights[1] or widths[0] != widths[1]:
                    continue
                ph, pw = heights[0], widths[0]

                present = []
                canonical = []
                for dr in range(2):
                    for dc in range(2):
                        shape = panels[i + dr][j + dc]
                        if shape:
                            present.append((dr, dc))
                            canonical.append(frozenset(
                                (ph - 1 - y if dr else y,
                                 pw - 1 - x if dc else x)
                                for y, x in shape
                            ))

                if len(present) != 3 or any(s != canonical[0] for s in canonical[1:]):
                    continue

                missing = next((dr, dc) for dr in range(2) for dc in range(2)
                               if (dr, dc) not in present)
                dr, dc = missing
                r0, _ = rb[i + dr]
                c0, _ = cb[j + dc]
                for y, x in canonical[0]:
                    yy = ph - 1 - y if dr else y
                    xx = pw - 1 - x if dc else x
                    out[r0 + yy][c0 + xx] = color

    return out
